update public.questions set options = '["Weil Jailbreak-Erkennung im Kurs als kontextabhängiges Verständnisproblem beschrieben wurde, während PII-Erkennung als reines Klassifikationsproblem gilt, das auch ein spezialisierter Transformer ohne LLM lösen kann", "Weil kleine, spezialisierte Transformer-Modelle aufgrund ihrer geringen Parameterzahl grundsätzlich keinerlei kontextuelle Zusammenhänge erkennen können, egal wie sie trainiert wurden", "Weil LLM-Aufrufe für Jailbreak-Checks laut EU AI Act ausdrücklich gesetzlich vorgeschrieben sind, PII-Checks dagegen nicht, unabhängig vom eingesetzten Modellanbieter", "Weil PII-Erkennung im Betrieb deutlich teurer ist als Jailbreak-Erkennung, da dafür laut Kurs pro Anfrage deutlich mehr Rechenleistung und Speicher nötig sind"]'::jsonb where id = '9ca9a1c2-1967-5c2f-b4c4-99d9c0a1140d';
update public.questions set options = '["TypeScript wird zur Laufzeit direkt vom Browser interpretiert, ganz ohne vorherige Kompilierung zu JavaScript", "TypeScript = JavaScript mit optionaler statischer Typisierung (ein Compiler prüft Typen, auch wenn nicht jeder Typ explizit angegeben werden muss)", "TypeScript ist die ältere Sprache, JavaScript gilt als deren modernere Weiterentwicklung mit ähnlicher Syntax", "TypeScript ist eine komplett eigenständige Programmiersprache ohne jeden syntaktischen oder historischen Bezug zu JavaScript"]'::jsonb where id = '79c87eb1-3ed4-5cdb-8d8e-7f2ad7f81227';
update public.questions set options = '["Er sorgt automatisch für DSGVO-Konformität des gesamten Systems, ganz ohne weitere Maßnahmen", "Er verschlüsselt die komplette Datenbank inklusive aller Backups auf Festplattenebene", "Er erkennt und schwärzt personenbezogene Daten in Ein- oder Ausgaben, bevor sie weiterverarbeitet oder geloggt werden", "Er ersetzt die Notwendigkeit eines menschlichen Prüfers (Human in the Loop) vollständig"]'::jsonb where id = '63d2d95d-28de-5a70-a573-b216d31564ce';
update public.questions set options = '["Die Daten (meist als JSON), die beim Aufruf an den Webhook übergeben werden", "Die Anzahl der Knoten, aus denen ein n8n-Workflow beim Empfang des Webhook-Aufrufs besteht", "Die maximale Antwortzeit, die ein Server für die Verarbeitung des Webhook-Aufrufs einhalten muss", "Der HTTP-Header, der den Datentyp der Anfrage beschreibt, etwa Content-Type: application/json"]'::jsonb where id = '2da85511-9364-54e2-a93b-268fc13ce66f';
update public.questions set options = '["Das Modell ist sich bei jeder einzelnen Token-Vorhersage vollständig sicher, unabhängig vom tatsächlichen Trainingskorpus", "Das Modell arbeitet besonders langsam, weil die Inferenz mit zusätzlichen Rechenschritten pro Token belastet wird", "Das Modell sagt die tatsächlich beobachtete Tokenfolge im Mittel gut vorher (ein Maß für Vorhersagbarkeit, nicht direkt für Textqualität)", "Das Modell kostet besonders viel pro Token, weil die Perplexity direkt in die Abrechnung der API einfließt"]'::jsonb where id = 'cdfd07e7-e372-597f-b0b9-e285299a58fe';
update public.questions set options = '["Ein Agent baut sich seinen Pfad vom Trigger zum Ziel selbst; beim Workflow legt der Mensch die Struktur vorher fest", "Ein Workflow läuft grundsätzlich nur einmal pro Trigger, während ein Agent dauerhaft und ohne Unterbrechung im Hintergrund weiterläuft", "Ein Workflow kann grundsätzlich keine KI-Knoten enthalten, während ein Agent ausschließlich aus KI-Knoten ohne klassische Logik besteht", "Ein Agent ist im Gegensatz zum Workflow immer deterministisch und liefert bei gleichem Input garantiert dasselbe Ergebnis"]'::jsonb where id = '79eb7557-3341-5dd6-8198-b9fa9ad361c2';
