update public.questions set options = '["Generative Pretrained Transformer", "Guided Prompt Technology (ein Verfahren, das Prompts automatisch anhand fester Vorlagen strukturiert)", "General Purpose Tool (eine Bezeichnung für universell einsetzbare Software ohne KI-Bezug)", "Global Processing Terminal (ein zentraler Server, der weltweit verteilte Rechenanfragen bündelt)"]'::jsonb where id = '0d5b8ff7-fdc0-5cf9-b272-b2b768919ed6';
update public.questions set options = '["Query Decomposition (das Zerlegen einer komplexen Anfrage in mehrere einfachere Teilfragen vor der Suche)", "Chain-of-Thought (das schrittweise Ausformulieren von Zwischengedanken vor der finalen Antwort)", "Re-Ranking (das nachträgliche Neusortieren bereits gefundener Suchergebnisse nach Relevanz)", "HyDE (Hypothetical Document Embeddings)"]'::jsonb where id = '55a8f9b5-1764-5e2c-af6a-e15cfb1d4706';
