update public.questions set options = '["Man fragt das Modell in mehreren Nachrichten hintereinander wiederholt nach seiner internen Modellversion und den Trainingsdaten", "Man schreibt ganz direkt und unverschlüsselt den Satz \"ignoriere alle vorherigen Anweisungen\" an den Anfang der Nachricht", "Man übersetzt den kompletten Systemprompt in eine andere Sprache, um Filter zu umgehen, die nur Deutsch prüfen", "Man tarnt die eigentliche Anfrage als Kinderschutz-Anliegen, um an dieselbe verbotene Information zu kommen"]'::jsonb where id = '5e90a87a-bad8-54cd-a538-2d201655e8da';
update public.questions set options = '["Die Verbindung wurde durch eine Firewall oder einen Proxy-Server aktiv blockiert, bevor sie den Zielserver erreicht", "Ein Server-Fehler, für den ausschließlich die Backend-Infrastruktur verantwortlich ist, nicht der Client", "Ein Fehler auf Client-Seite (z. B. eine ungültige oder fehlerhafte Anfrage)", "Die Anfrage wurde erfolgreich angenommen und wird asynchron im Hintergrund weiterverarbeitet, das Ergebnis kommt später"]'::jsonb where id = '426ce262-910a-5b19-a244-56571fe6323f';
